package com.arjunren.hospital.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="doctors",indexes=@Index(name="doctors_specialty_idx",columnList="specialty"))public class DoctorProfile{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@OneToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="user_id",unique=true)private AppUser user;@Column(nullable=false,unique=true,length=40)private String licenseNumber;@Column(nullable=false,length=120)private String specialty;@Column(name="slot_minutes",nullable=false)private int slotMinutes=30;@Column(nullable=false)private boolean active=true;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt=Instant.now();protected DoctorProfile(){}public DoctorProfile(AppUser u,String l,String s,int m){user=u;licenseNumber=l;specialty=s;slotMinutes=m;}public Long getId(){return id;}public AppUser getUser(){return user;}public String getLicenseNumber(){return licenseNumber;}public String getSpecialty(){return specialty;}public int getSlotMinutes(){return slotMinutes;}public boolean isActive(){return active;}}

